package decision

import (
	"context"
	"errors"
	"testing"

	"github.com/jackc/pgx/v5/pgtype"

	"github.com/memohai/memoh/internal/db/postgres/sqlc"
	dbstore "github.com/memohai/memoh/internal/db/store"
)

type createTransactionQueries struct {
	dbstore.Queries
	parentLocked  bool
	sessionLocked bool
}

func (*createTransactionQueries) SupportsTransactions() bool { return true }

func (q *createTransactionQueries) InTx(_ context.Context, fn func(dbstore.Queries) error) error {
	return fn(q)
}

func (q *createTransactionQueries) LockBotForSessionWrite(_ context.Context, id pgtype.UUID) (pgtype.UUID, error) {
	q.parentLocked = true
	return id, nil
}

func (q *createTransactionQueries) LockSessionDecisionSequence(_ context.Context, _ sqlc.LockSessionDecisionSequenceParams) (pgtype.UUID, error) {
	if !q.parentLocked {
		return pgtype.UUID{}, errors.New("session locked before bot parent")
	}
	q.sessionLocked = true
	return pgtype.UUID{Valid: true}, nil
}

func TestInCreateTransactionLocksBotBeforeSession(t *testing.T) {
	t.Parallel()

	queries := &createTransactionQueries{}
	called := false
	err := InCreateTransaction(context.Background(), queries,
		"11111111-1111-1111-1111-111111111111",
		"22222222-2222-2222-2222-222222222222",
		func(dbstore.Queries) error {
			called = true
			if !queries.parentLocked || !queries.sessionLocked {
				t.Fatal("create callback ran before parent and session locks")
			}
			return nil
		})
	if err != nil {
		t.Fatalf("InCreateTransaction() error = %v", err)
	}
	if !called {
		t.Fatal("create callback did not run")
	}
}

package input

import "testing"

func interactionTestPayload() UIPayload {
	return UIPayload{
		Version: PayloadVersion,
		Questions: []UIQuestion{
			{
				ID: "q1", Text: "Pick", Kind: QuestionKindSingleSelect,
				Options: []UIOption{{ID: "q1.o1", Label: "A"}, {ID: "q1.o2", Label: "B"}},
			},
			{
				ID: "q2", Text: "Multi", Kind: QuestionKindMultiSelect, AllowCustom: true,
				Options: []UIOption{{ID: "q2.o1", Label: "X"}, {ID: "q2.o2", Label: "Y"}},
			},
			{ID: "q3", Text: "Free", Kind: QuestionKindText},
		},
	}
}

func TestApplyInteractionOpCompletedIsUnchanged(t *testing.T) {
	t.Parallel()

	// Crash window: completed-but-unsubmitted state must not mutate; the
	// caller re-drives submission off the unchanged completed state.
	state := TextInteractionState{Completed: true, QuestionIndex: 2}
	next, outcome := ApplyInteractionOp(interactionTestPayload(), state, InteractionOp{Kind: OpToggleOption, QuestionIndex: 1, OptionIndex: 0})
	if outcome.Changed || outcome.Reject != RejectNone || !next.Completed {
		t.Fatalf("completed state must be inert: %#v %#v", next, outcome)
	}
}

func TestApplyInteractionOpRejects(t *testing.T) {
	t.Parallel()

	payload := interactionTestPayload()
	cases := []struct {
		name string
		op   InteractionOp
		want InteractionReject
	}{
		{"nav out of range", InteractionOp{Kind: OpNavigate, Page: 9}, RejectInvalidOp},
		{"select bad option", InteractionOp{Kind: OpSelectOption, QuestionIndex: 0, OptionIndex: 9}, RejectInvalidOp},
		{"set_text unknown question", InteractionOp{Kind: OpSetText, QuestionID: "nope", Text: "x"}, RejectInvalidOp},
		{"set_text empty", InteractionOp{Kind: OpSetText, QuestionID: "q3", Text: "  "}, RejectEmptyText},
		{"custom not allowed", InteractionOp{Kind: OpSetText, QuestionID: "q1", Text: "x"}, RejectCustomNotAllowed},
		{"unknown kind", InteractionOp{Kind: "bogus"}, RejectInvalidOp},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			_, outcome := ApplyInteractionOp(payload, TextInteractionState{}, tc.op)
			if outcome.Reject != tc.want || outcome.Changed {
				t.Fatalf("outcome = %#v, want reject %q", outcome, tc.want)
			}
		})
	}
}

func TestApplyInteractionOpToggleClearRemovesAnswer(t *testing.T) {
	t.Parallel()

	payload := interactionTestPayload()
	state := TextInteractionState{QuestionIndex: 1}
	state, _ = ApplyInteractionOp(payload, state, InteractionOp{Kind: OpToggleOption, QuestionIndex: 1, OptionIndex: 0})
	if answer, ok := state.Answer("q2"); !ok || len(answer.OptionIDs) != 1 {
		t.Fatalf("toggle on = %#v", state)
	}
	state, _ = ApplyInteractionOp(payload, state, InteractionOp{Kind: OpToggleOption, QuestionIndex: 1, OptionIndex: 0})
	if _, ok := state.Answer("q2"); ok {
		t.Fatalf("toggle off must remove the answer entry: %#v", state)
	}
}

func TestApplyInteractionOpSubmitSatisfiesSubmittedResult(t *testing.T) {
	t.Parallel()

	// The completed answer set must pass Submit's every-question contract.
	payload := interactionTestPayload()
	state, outcome := ApplyInteractionOp(payload, TextInteractionState{}, InteractionOp{Kind: OpSelectOption, QuestionIndex: 0, OptionIndex: 1})
	if !outcome.Changed || state.QuestionIndex != 1 {
		t.Fatalf("select = %#v %#v", state, outcome)
	}
	state, _ = ApplyInteractionOp(payload, state, InteractionOp{Kind: OpSubmit})
	if !state.Completed {
		t.Fatalf("submit = %#v", state)
	}
	if _, err := submittedResult(payload, state.Answers); err != nil {
		t.Fatalf("submittedResult: %v", err)
	}
}

func TestApplyInteractionOpSameSelectionTogglesOffWithoutAdvance(t *testing.T) {
	t.Parallel()

	payload := interactionTestPayload()
	state, _ := ApplyInteractionOp(payload, TextInteractionState{}, InteractionOp{Kind: OpSelectOption, QuestionIndex: 0, OptionIndex: 0})
	state, outcome := ApplyInteractionOp(payload, state, InteractionOp{Kind: OpSelectOption, QuestionIndex: 0, OptionIndex: 0})
	if !outcome.Changed || state.QuestionIndex != 0 {
		t.Fatalf("clear = %#v %#v", state, outcome)
	}
	if _, ok := state.Answer("q1"); ok {
		t.Fatalf("re-select must clear: %#v", state)
	}
}

package compaction

import (
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgtype"

	contextfrag "github.com/memohai/memoh/internal/agent/context/fragment"
)

func TestDecodeArtifactCoverageAcceptsStrictAndLegacyEmptyCoverage(t *testing.T) {
	t.Parallel()

	strict := strictTestCoveredSource("row-1", 1)
	decoded, err := DecodeArtifactCoverage(mustMarshalCoverage(t, strict))
	if err != nil {
		t.Fatalf("DecodeArtifactCoverage(strict) error = %v", err)
	}
	if len(decoded) != 1 || decoded[0].Ref.ContentHash != strict.Ref.ContentHash {
		t.Fatalf("DecodeArtifactCoverage(strict) = %#v", decoded)
	}

	for _, raw := range [][]byte{nil, []byte(" "), []byte("null"), []byte("[]")} {
		decoded, err := DecodeArtifactCoverage(raw)
		if err != nil || len(decoded) != 0 {
			t.Fatalf("DecodeArtifactCoverage(%q) = %#v, %v; want empty coverage", raw, decoded, err)
		}
	}
}

func TestDecodeArtifactCoverageRejectsInvalidPersistedCoverage(t *testing.T) {
	t.Parallel()

	missingHashIdentity := strictTestCoveredSource("missing-hash-identity", 1)
	missingHashIdentity.Ref.HashAlgo = ""
	missingHashIdentity.Ref.HashScope = ""
	missingHashIdentity.Ref.ContentHash = ""

	emptyContentHash := strictTestCoveredSource("empty-content-hash", 1)
	emptyContentHash.Ref.ContentHash = " "

	canonicalScope := strictTestCoveredSource("canonical-scope", 1)
	canonicalScope.Ref.HashScope = contextfrag.HashScopeCanonicalFragment

	duplicate := strictTestCoveredSource("duplicate", 1)
	newer := strictTestCoveredSource("newer", 2)
	older := strictTestCoveredSource("older", 1)

	tests := []struct {
		name    string
		covered []CoveredSource
		wantErr string
	}{
		{name: "missing hash identity", covered: []CoveredSource{missingHashIdentity}, wantErr: "sha256"},
		{name: "empty content hash", covered: []CoveredSource{emptyContentHash}, wantErr: "content hash"},
		{name: "canonical hash scope", covered: []CoveredSource{canonicalScope}, wantErr: "source_payload"},
		{name: "duplicate stable key", covered: []CoveredSource{duplicate, duplicate}, wantErr: "duplicate"},
		{name: "decreasing creation time", covered: []CoveredSource{newer, older}, wantErr: "created_at_ms"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			_, err := DecodeArtifactCoverage(mustMarshalCoverage(t, tt.covered...))
			if err == nil || !strings.Contains(err.Error(), tt.wantErr) {
				t.Fatalf("DecodeArtifactCoverage() error = %v, want containing %q", err, tt.wantErr)
			}
		})
	}
}

func TestCoverageIncludesRequiresExactPersistedHash(t *testing.T) {
	t.Parallel()

	strict := strictTestCoveredSource("row-1", 1)
	hashless := strict
	hashless.Ref.HashAlgo = ""
	hashless.Ref.HashScope = ""
	hashless.Ref.ContentHash = ""

	if !coverageIncludes([]CoveredSource{strict}, []CoveredSource{strict}) {
		t.Fatal("identical strict coverage did not match")
	}
	if coverageIncludes([]CoveredSource{strict}, []CoveredSource{hashless}) {
		t.Fatal("hashless required coverage acted as a wildcard")
	}
	if coverageIncludes([]CoveredSource{hashless}, []CoveredSource{hashless}) {
		t.Fatal("hashless persisted coverage matched itself")
	}
}

func TestArtifactFrontierRejectsDerivedCoverageThatReordersParentSources(t *testing.T) {
	t.Parallel()

	parent := testArtifact("ordered-parent")
	child := testArtifact("reordered-child")
	parent.SupersededBy = child.ID
	parent.SupersededAt = time.Unix(1, 0)
	parent.Coverage = testCoverage("row-1", "row-2")
	child.ParentIDs = []string{parent.ID}
	child.Coverage = testCoverage("row-2", "row-1")
	for i := range parent.Coverage {
		parent.Coverage[i].CreatedAtMs = 1
		child.Coverage[i].CreatedAtMs = 1
	}

	frontier := buildArtifactFrontier([]Artifact{parent, child})
	if len(frontier.Artifacts) != 0 || !hasLineageIssue(frontier.Issues, LineageIssueCoverageMismatch) {
		t.Fatalf("reordered derived coverage remained active: artifacts=%#v issues=%#v", frontier.Artifacts, frontier.Issues)
	}
}

func TestArtifactFrontierRejectsDerivedCoverageThatReordersParentSegments(t *testing.T) {
	t.Parallel()

	parentA := testArtifact("parent-a")
	parentB := testArtifact("parent-b")
	child := testArtifact("reordered-child")
	parentA.SupersededBy = child.ID
	parentA.SupersededAt = time.Unix(1, 0)
	parentA.Coverage = testCoverage("row-a")
	parentB.SupersededBy = child.ID
	parentB.SupersededAt = time.Unix(1, 0)
	parentB.Coverage = testCoverage("row-b")
	child.ParentIDs = []string{parentA.ID, parentB.ID}
	child.Coverage = testCoverage("row-b", "row-a")

	frontier := buildArtifactFrontier([]Artifact{parentA, parentB, child})
	if len(frontier.Artifacts) != 0 || !hasLineageIssue(frontier.Issues, LineageIssueCoverageMismatch) {
		t.Fatalf("reordered parent segments remained active: artifacts=%#v issues=%#v", frontier.Artifacts, frontier.Issues)
	}
}

func TestArtifactFrontierRejectsDerivedCoverageThatRewritesParentMetadata(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		mutate func(*CoveredSource)
	}{
		{name: "created at", mutate: func(source *CoveredSource) { source.CreatedAtMs++ }},
		{name: "external message id", mutate: func(source *CoveredSource) { source.ExternalMessageID = "changed" }},
		{name: "reply target", mutate: func(source *CoveredSource) { source.SourceReplyToMessageID = "changed" }},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			parent := testArtifact("metadata-parent")
			child := testArtifact("metadata-child")
			parent.SupersededBy = child.ID
			parent.SupersededAt = time.Unix(1, 0)
			parent.Coverage = testCoverage("row-1")
			parent.Coverage[0].ExternalMessageID = "external-1"
			parent.Coverage[0].SourceReplyToMessageID = "reply-1"
			child.ParentIDs = []string{parent.ID}
			child.Coverage = append([]CoveredSource(nil), parent.Coverage...)
			tt.mutate(&child.Coverage[0])

			frontier := buildArtifactFrontier([]Artifact{parent, child})
			if len(frontier.Artifacts) != 0 || !hasLineageIssue(frontier.Issues, LineageIssueCoverageMismatch) {
				t.Fatalf("rewritten parent metadata remained active: artifacts=%#v issues=%#v", frontier.Artifacts, frontier.Issues)
			}
		})
	}
}

func TestPersistedMalformedOrHashlessLineageCoverageIsQuarantined(t *testing.T) {
	t.Parallel()

	hashless := strictTestCoveredSource("hashless-row", 1)
	hashless.Ref.HashAlgo = ""
	hashless.Ref.HashScope = ""
	hashless.Ref.ContentHash = ""

	tests := []struct {
		name     string
		coverage []byte
	}{
		{name: "malformed", coverage: []byte("{")},
		{name: "hashless", coverage: mustMarshalCoverage(t, hashless)},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			row := projectionRow(t, "00000000-0000-0000-0000-00000000da01")
			row.ParentIds = []pgtype.UUID{mustProjectionUUID(t, "00000000-0000-0000-0000-00000000da02")}
			row.Coverage = tt.coverage
			artifact, err := artifactFromDBRow(row)
			if err != nil {
				t.Fatalf("artifactFromDBRow() error = %v", err)
			}
			if !artifact.CoverageMalformed {
				t.Fatal("invalid persisted coverage was not marked malformed")
			}

			frontier := buildArtifactFrontier([]Artifact{artifact})
			if len(frontier.Artifacts) != 0 || !hasLineageIssue(frontier.Issues, LineageIssueMalformedCoverage) {
				t.Fatalf("invalid lineage coverage was not quarantined: frontier=%#v issues=%#v", frontier.Artifacts, frontier.Issues)
			}
		})
	}
}

func TestArtifactProjectionQuarantinesCoverageAnchorMismatch(t *testing.T) {
	t.Parallel()

	row := projectionRow(t, "00000000-0000-0000-0000-00000000da03")
	row.Coverage = testCoverageJSON(t, "anchor-row")
	row.AnchorStartMs = 0
	row.AnchorEndMs = 2
	artifact, err := artifactFromDBRow(row)
	if err != nil {
		t.Fatalf("artifactFromDBRow() error = %v", err)
	}
	if !artifact.CoverageMalformed {
		t.Fatal("coverage/anchor mismatch was not marked malformed")
	}

	frontier := buildArtifactFrontier([]Artifact{artifact})
	if len(frontier.Artifacts) != 0 || !hasLineageIssue(frontier.Issues, LineageIssueMalformedCoverage) {
		t.Fatalf("coverage/anchor mismatch remained active: frontier=%#v issues=%#v", frontier.Artifacts, frontier.Issues)
	}
}

func strictTestCoveredSource(id string, createdAtMs int64) CoveredSource {
	return CoveredSource{
		Ref: contextfrag.ContextRef{
			Namespace:   "bot_history_message",
			ID:          id,
			Version:     1,
			HashAlgo:    contextfrag.HashAlgoSHA256,
			HashScope:   contextfrag.HashScopeSourcePayload,
			ContentHash: "hash-" + id,
			Schema:      contextfrag.SchemaContextRef,
			Durability:  contextfrag.RefDurable,
		},
		CreatedAtMs: createdAtMs,
	}
}

func mustMarshalCoverage(t *testing.T, covered ...CoveredSource) []byte {
	t.Helper()
	raw, err := json.Marshal(covered)
	if err != nil {
		t.Fatalf("marshal coverage: %v", err)
	}
	return raw
}

package decision

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/memohai/memoh/internal/db"
	"github.com/memohai/memoh/internal/db/postgres/sqlc"
	dbstore "github.com/memohai/memoh/internal/db/store"
	"github.com/memohai/memoh/internal/runtimefence"
)

type transactionRunner interface {
	InTx(context.Context, func(dbstore.Queries) error) error
}

type transactionCapability interface {
	SupportsTransactions() bool
}

type sequenceLocker interface {
	LockSessionDecisionSequence(context.Context, sqlc.LockSessionDecisionSequenceParams) (pgtype.UUID, error)
}

// InCreateTransaction serializes per-session decision short IDs before the
// INSERT statement takes its MVCC snapshot. Non-transactional test stores
// retain their own local serialization.
func InCreateTransaction(ctx context.Context, queries dbstore.Queries, botID, sessionID string, create func(dbstore.Queries) error) error {
	if create == nil {
		return errors.New("decision create callback is required")
	}
	if _, fenced := runtimefence.FromContext(ctx); fenced {
		return runtimefence.InTransaction(ctx, queries, botID, sessionID, func(txQueries dbstore.Queries) error {
			return lockAndCreate(ctx, txQueries, botID, sessionID, create)
		})
	}
	txer, txOK := queries.(transactionRunner)
	capability, capabilityOK := queries.(transactionCapability)
	if !txOK || !capabilityOK || !capability.SupportsTransactions() {
		return create(queries)
	}
	return txer.InTx(ctx, func(txQueries dbstore.Queries) error {
		return lockAndCreate(ctx, txQueries, botID, sessionID, create)
	})
}

func lockAndCreate(ctx context.Context, queries dbstore.Queries, botID, sessionID string, create func(dbstore.Queries) error) error {
	pgBotID, err := db.ParseUUID(botID)
	if err != nil {
		return err
	}
	pgSessionID, err := db.ParseUUID(sessionID)
	if err != nil {
		return err
	}
	if err := runtimefence.LockBotForSessionWrite(ctx, queries, botID); err != nil {
		return err
	}
	locker, ok := queries.(sequenceLocker)
	if !ok {
		return errors.New("decision store does not support session sequence locking")
	}
	if _, err := locker.LockSessionDecisionSequence(ctx, sqlc.LockSessionDecisionSequenceParams{
		SessionID: pgSessionID,
		BotID:     pgBotID,
	}); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return runtimefence.ErrStale
		}
		return err
	}
	return create(queries)
}

package input

import (
	"context"
	"encoding/json"
	"errors"
	"strings"

	"github.com/jackc/pgx/v5"

	"github.com/memohai/memoh/internal/db"
	"github.com/memohai/memoh/internal/db/postgres/sqlc"
)

// Structured ask_user gestures from channels with native controls (inline
// buttons). They drive the same durable TextInteractionState as plain-text
// replies (AdvanceText) — one state machine, two input surfaces — so an
// interaction survives process restarts regardless of which surface it uses.
type InteractionOpKind string

const (
	// OpSelectOption answers a single_select question and auto-advances;
	// re-selecting the current choice clears it (toggle-off).
	OpSelectOption InteractionOpKind = "select"
	// OpToggleOption flips one multi_select option; never advances.
	OpToggleOption InteractionOpKind = "toggle"
	// OpSetText records a verbatim free-text answer (text question or
	// allow_custom). Unlike AdvanceText it never option-matches the input:
	// the user explicitly chose to type, so the text is taken as-is.
	OpSetText InteractionOpKind = "set_text"
	// OpNavigate moves the question cursor without touching answers.
	OpNavigate InteractionOpKind = "navigate"
	// OpSubmit completes the request, marking unanswered questions skipped.
	OpSubmit InteractionOpKind = "submit"
)

// InteractionReject explains why an op did not apply. Rejections are
// user-correctable (wrong button state, empty text) — not errors.
type InteractionReject string

const (
	RejectNone             InteractionReject = ""
	RejectInvalidOp        InteractionReject = "invalid_op"
	RejectCustomNotAllowed InteractionReject = "custom_not_allowed"
	RejectEmptyText        InteractionReject = "empty_text"
)

type InteractionOp struct {
	Kind InteractionOpKind
	// QuestionIndex/OptionIndex address buttons for select/toggle; indexes
	// are stable because UIPayload question/option order never changes after
	// CreatePending.
	QuestionIndex int
	OptionIndex   int
	// Page is the navigate target.
	Page int
	// QuestionID binds set_text to the question that requested free text,
	// not to the current cursor — navigation may have moved since the
	// prompt was issued.
	QuestionID string
	Text       string
}

type AdvanceInteractionInput struct {
	BotID     string
	RequestID string
	Op        InteractionOp
}

type AdvanceInteractionResult struct {
	// Handled is false when the request no longer exists or is not pending
	// (already answered, canceled, expired) — callers should tell the user
	// the interaction ended rather than surface an error.
	Handled bool
	// Changed reports whether state was persisted; unchanged ops (same-page
	// nav, replay after completion) need no card re-render.
	Changed bool
	Reject  InteractionReject
	Request Request
}

// AdvanceInteraction applies one structured op to the durable interaction
// state under the same optimistic-lock CAS as AdvanceText: each attempt
// re-reads the row and re-applies the op, so a concurrent writer never makes
// a stale gesture win.
func (s *Service) AdvanceInteraction(ctx context.Context, input AdvanceInteractionInput) (AdvanceInteractionResult, error) {
	if s == nil || s.queries == nil {
		return AdvanceInteractionResult{}, errors.New("user input queries not configured")
	}
	resolve := ResolveInput{
		BotID:      input.BotID,
		ExplicitID: strings.TrimSpace(input.RequestID),
	}
	if resolve.ExplicitID == "" {
		return AdvanceInteractionResult{}, errors.New("user input request id is required")
	}
	for attempt := 0; attempt < maxTextInteractionRetries; attempt++ {
		req, err := s.ResolveTarget(ctx, resolve)
		if errors.Is(err, ErrNotFound) {
			return AdvanceInteractionResult{Handled: false}, nil
		}
		if err != nil {
			return AdvanceInteractionResult{}, err
		}
		state, outcome := ApplyInteractionOp(req.UIPayload, req.Interaction, input.Op)
		if outcome.Reject != RejectNone || !outcome.Changed {
			req.Interaction = state
			return AdvanceInteractionResult{Handled: true, Reject: outcome.Reject, Request: req}, nil
		}
		updated, ok, err := s.persistInteraction(ctx, req, state)
		if err != nil {
			return AdvanceInteractionResult{}, err
		}
		if ok {
			return AdvanceInteractionResult{Handled: true, Changed: true, Request: updated}, nil
		}
	}
	return AdvanceInteractionResult{}, errors.New("user input changed concurrently; retry the action")
}

// persistInteraction CAS-writes state at req's revision. ok=false means the
// row moved underneath us (revision bumped, request resolved, or expired) and
// the caller should re-resolve and re-apply its input.
func (s *Service) persistInteraction(ctx context.Context, req Request, state TextInteractionState) (Request, bool, error) {
	stateJSON, err := json.Marshal(state)
	if err != nil {
		return Request{}, false, err
	}
	id, err := db.ParseUUID(req.ID)
	if err != nil {
		return Request{}, false, err
	}
	row, err := s.queries.UpdateUserInputInteraction(ctx, sqlc.UpdateUserInputInteractionParams{
		InteractionJson:     stateJSON,
		ID:                  id,
		InteractionRevision: int32(req.InteractionRevision), //nolint:gosec // revisions cannot approach int32 during one request.
	})
	if err == nil {
		return requestFromRow(row), true, nil
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return Request{}, false, nil
	}
	return Request{}, false, err
}

type InteractionOutcome struct {
	Changed bool
	Reject  InteractionReject
}

// ApplyInteractionOp is the pure transition function for button-driven input.
// It mirrors the plain-text transitions in advanceTextState where the
// semantics overlap (advance-on-answer, complete-on-last, skip fill).
func ApplyInteractionOp(payload UIPayload, state TextInteractionState, op InteractionOp) (TextInteractionState, InteractionOutcome) {
	if len(payload.Questions) == 0 {
		return state, InteractionOutcome{Reject: RejectInvalidOp}
	}
	state = normalizeTextInteraction(payload, state)
	if state.Completed {
		// Crash window: the final answer set was persisted but submission
		// did not run. Report unchanged so the caller re-drives submission
		// instead of mutating an already-complete answer set.
		return state, InteractionOutcome{}
	}
	switch op.Kind {
	case OpNavigate:
		if op.Page < 0 || op.Page >= len(payload.Questions) {
			return state, InteractionOutcome{Reject: RejectInvalidOp}
		}
		if state.QuestionIndex == op.Page {
			return state, InteractionOutcome{}
		}
		state.QuestionIndex = op.Page
		return state, InteractionOutcome{Changed: true}
	case OpSelectOption:
		return applySelectOption(payload, state, op)
	case OpToggleOption:
		return applyToggleOption(payload, state, op)
	case OpSetText:
		return applySetText(payload, state, op)
	case OpSubmit:
		state.Answers = fillSkippedAnswers(payload, state.Answers)
		state.Completed = true
		return state, InteractionOutcome{Changed: true}
	default:
		return state, InteractionOutcome{Reject: RejectInvalidOp}
	}
}

func applySelectOption(payload UIPayload, state TextInteractionState, op InteractionOp) (TextInteractionState, InteractionOutcome) {
	question, ok := interactionQuestionAt(payload, op.QuestionIndex)
	if !ok || op.OptionIndex < 0 || op.OptionIndex >= len(question.Options) {
		return state, InteractionOutcome{Reject: RejectInvalidOp}
	}
	// Realign the cursor to the tapped question: a late callback may arrive
	// after navigation moved elsewhere.
	state.QuestionIndex = op.QuestionIndex
	optionID := question.Options[op.OptionIndex].ID
	answer, answered := state.Answer(question.ID)
	if answered && len(answer.OptionIDs) == 1 && answer.OptionIDs[0] == optionID && answer.CustomText == "" {
		// Re-tapping the current choice clears it; the user stays to pick
		// again or skip.
		state.Answers = removeTextAnswer(state.Answers, question.ID)
		return state, InteractionOutcome{Changed: true}
	}
	state.Answers = putTextAnswer(state.Answers, QuestionAnswer{QuestionID: question.ID, OptionIDs: []string{optionID}})
	if op.QuestionIndex < len(payload.Questions)-1 {
		state.QuestionIndex = op.QuestionIndex + 1
	} else {
		// Answering the last question completes the set; earlier questions
		// deliberately left blank become skips, same as plain-text "skip".
		state.Answers = fillSkippedAnswers(payload, state.Answers)
		state.Completed = true
	}
	return state, InteractionOutcome{Changed: true}
}

func applyToggleOption(payload UIPayload, state TextInteractionState, op InteractionOp) (TextInteractionState, InteractionOutcome) {
	question, ok := interactionQuestionAt(payload, op.QuestionIndex)
	if !ok || op.OptionIndex < 0 || op.OptionIndex >= len(question.Options) {
		return state, InteractionOutcome{Reject: RejectInvalidOp}
	}
	state.QuestionIndex = op.QuestionIndex
	answer, _ := state.Answer(question.ID)
	answer.QuestionID = question.ID
	answer.Skipped = false
	answer.OptionIDs = toggleOptionID(answer.OptionIDs, question.Options[op.OptionIndex].ID)
	if len(answer.OptionIDs) == 0 && strings.TrimSpace(answer.CustomText) == "" {
		state.Answers = removeTextAnswer(state.Answers, question.ID)
	} else {
		state.Answers = putTextAnswer(state.Answers, answer)
	}
	return state, InteractionOutcome{Changed: true}
}

func applySetText(payload UIPayload, state TextInteractionState, op InteractionOp) (TextInteractionState, InteractionOutcome) {
	text := strings.TrimSpace(op.Text)
	if text == "" {
		return state, InteractionOutcome{Reject: RejectEmptyText}
	}
	questionIndex := -1
	for idx, question := range payload.Questions {
		if question.ID == strings.TrimSpace(op.QuestionID) {
			questionIndex = idx
			break
		}
	}
	if questionIndex < 0 {
		return state, InteractionOutcome{Reject: RejectInvalidOp}
	}
	question := payload.Questions[questionIndex]
	state.QuestionIndex = questionIndex
	switch question.Kind {
	case QuestionKindText:
		state.Answers = putTextAnswer(state.Answers, QuestionAnswer{QuestionID: question.ID, Text: text})
	case QuestionKindSingleSelect:
		if !question.AllowCustom {
			return state, InteractionOutcome{Reject: RejectCustomNotAllowed}
		}
		state.Answers = putTextAnswer(state.Answers, QuestionAnswer{QuestionID: question.ID, CustomText: text})
	case QuestionKindMultiSelect:
		if !question.AllowCustom {
			return state, InteractionOutcome{Reject: RejectCustomNotAllowed}
		}
		// Custom text joins any options already toggled; the user may keep
		// toggling, so multi-select never auto-advances on text.
		answer, _ := state.Answer(question.ID)
		answer.QuestionID = question.ID
		answer.Skipped = false
		answer.CustomText = text
		state.Answers = putTextAnswer(state.Answers, answer)
		return state, InteractionOutcome{Changed: true}
	default:
		state.Answers = putTextAnswer(state.Answers, QuestionAnswer{QuestionID: question.ID, Text: text})
	}
	if questionIndex < len(payload.Questions)-1 {
		state.QuestionIndex = questionIndex + 1
	} else {
		state.Answers = fillSkippedAnswers(payload, state.Answers)
		state.Completed = true
	}
	return state, InteractionOutcome{Changed: true}
}

// fillSkippedAnswers appends explicit skip entries for unanswered questions so
// the completed set satisfies Submit's every-question-answered contract.
func fillSkippedAnswers(payload UIPayload, answers []QuestionAnswer) []QuestionAnswer {
	out := append([]QuestionAnswer(nil), answers...)
	have := make(map[string]struct{}, len(out))
	for _, answer := range out {
		have[answer.QuestionID] = struct{}{}
	}
	for _, question := range payload.Questions {
		if _, ok := have[question.ID]; !ok {
			out = append(out, QuestionAnswer{QuestionID: question.ID, Skipped: true})
		}
	}
	return out
}

func removeTextAnswer(answers []QuestionAnswer, questionID string) []QuestionAnswer {
	out := make([]QuestionAnswer, 0, len(answers))
	for _, answer := range answers {
		if answer.QuestionID == questionID {
			continue
		}
		out = append(out, answer)
	}
	return out
}

func toggleOptionID(ids []string, target string) []string {
	out := make([]string, 0, len(ids)+1)
	found := false
	for _, id := range ids {
		if id == target {
			found = true
			continue
		}
		out = append(out, id)
	}
	if !found {
		out = append(out, target)
	}
	return out
}

func interactionQuestionAt(payload UIPayload, index int) (UIQuestion, bool) {
	if index < 0 || index >= len(payload.Questions) {
		return UIQuestion{}, false
	}
	return payload.Questions[index], true
}

