func TestReplaceRecentCompactedMessagesFollowsSupersession(t *testing.T) {
	t.Parallel()

	parentID := "00000000-0000-0000-0000-00000000c011"
	activeID := "00000000-0000-0000-0000-00000000c012"
	coverage := persistedCoverage(t, "row-parent")
	parent := sqlc.BotHistoryMessageCompact{
		ID:           mustPGUUID(t, parentID),
		Status:       "ok",
		Summary:      "stale parent summary",
		Coverage:     coverage,
		SupersededBy: mustPGUUID(t, activeID),
		SupersededAt: pgtype.Timestamptz{Time: time.Unix(10, 0), Valid: true},
	}
	active := sqlc.BotHistoryMessageCompact{
		ID:        mustPGUUID(t, activeID),
		Status:    "ok",
		Summary:   "active restacked summary",
		Coverage:  coverage,
		ParentIds: []pgtype.UUID{mustPGUUID(t, parentID)},
	}
	queries := &recordingCompactionLogQueries{
		byID: map[pgtype.UUID]sqlc.BotHistoryMessageCompact{
			parent.ID: parent,
			active.ID: active,
		},
	}
	resolver := &Service{queries: queries}
	recent := []historyfrag.HistoryRecord{
		historyRecord("row-parent", ModelMessage{Role: "user", Content: newTextContent("covered by parent")}, func(record *historyfrag.HistoryRecord) {
			record.CompactID = parentID
		}),
	}

	got := mustReplaceCompactedMessages(t, resolver, "", contextfrag.Scope{}, recent)

	if len(got) != 1 || got[0].CompactID != activeID {
		t.Fatalf("sessionless superseded group must resolve to active artifact %s: %#v", activeID, got)
	}
	if len(queries.getCalls) != 2 || queries.getCalls[0] != parent.ID || queries.getCalls[1] != active.ID {
		t.Fatalf("lineage lookups = %#v, want parent then active", queries.getCalls)
	}
}

func TestReplaceRecentCompactedMessagesUsesRecordSessionAsOwner(t *testing.T) {
	t.Parallel()

	botID := "00000000-0000-0000-0000-00000000b101"
	recordSessionID := "00000000-0000-0000-0000-00000000f101"
	foreignSessionID := "00000000-0000-0000-0000-00000000f102"
	foreignCompactID := "00000000-0000-0000-0000-00000000c101"
	foreign := sqlc.BotHistoryMessageCompact{
		ID:        mustPGUUID(t, foreignCompactID),
		BotID:     mustPGUUID(t, botID),
		SessionID: mustPGUUID(t, foreignSessionID),
		Status:    "ok",
		Summary:   "foreign session summary",
	}
	queries := &recordingCompactionLogQueries{
		byID: map[pgtype.UUID]sqlc.BotHistoryMessageCompact{foreign.ID: foreign},
	}
	resolver := &Service{queries: queries}
	recent := []historyfrag.HistoryRecord{
		historyRecord("row-owned-by-session", ModelMessage{Role: "user", Content: newTextContent("keep local raw")}, func(record *historyfrag.HistoryRecord) {
			record.BotID = botID
			record.SessionID = recordSessionID
			record.CompactID = foreignCompactID
		}),
	}

	got := mustReplaceCompactedMessages(t, resolver, "", contextfrag.Scope{BotID: botID}, recent)

	if gotText := recordTexts(got); !reflect.DeepEqual(gotText, []string{"keep local raw"}) {
		t.Fatalf("cross-session artifact replaced local history: %#v", gotText)
	}
	if len(queries.getCalls) != 0 {
		t.Fatalf("session-owned group fell back to unscoped point lookup: %#v", queries.getCalls)
	}
}

package application

import (
	"testing"
	"time"
)

func TestSessionCompactionWaitsForEveryOutboundAssetLinker(t *testing.T) {
	t.Parallel()

	resolver := &Service{}
	releaseFirst := resolver.DeferSessionCompaction("bot-1", "session-1", "run-1")
	releaseSecond := resolver.DeferSessionCompaction("bot-1", "session-1", "run-2")
	compactionEntered := make(chan struct{})
	releaseCompaction := make(chan struct{})
	go func() {
		done := resolver.enterSessionCompaction("bot-1", "session-1")
		close(compactionEntered)
		<-releaseCompaction
		done()
	}()

	releaseFirst()
	assertChannelBlocked(t, compactionEntered, "compaction started while one asset linker remained")
	releaseSecond()
	assertChannelReady(t, compactionEntered, "compaction did not start after every asset linker finished")
	close(releaseCompaction)
}

func TestWaitingSessionCompactionBlocksLaterAssetLinkers(t *testing.T) {
	t.Parallel()

	resolver := &Service{}
	releaseFirst := resolver.DeferSessionCompaction("bot-1", "session-1", "run-1")
	compactionEntered := make(chan struct{})
	releaseCompaction := make(chan struct{})
	go func() {
		done := resolver.enterSessionCompaction("bot-1", "session-1")
		close(compactionEntered)
		<-releaseCompaction
		done()
	}()
	assertChannelBlocked(t, compactionEntered, "compaction ignored an active asset linker")

	secondEntered := make(chan func(), 1)
	go func() {
		secondEntered <- resolver.DeferSessionCompaction("bot-1", "session-1", "run-2")
	}()
	releaseFirst()
	assertChannelReady(t, compactionEntered, "waiting compaction did not acquire the session gate")
	assertChannelBlocked(t, secondEntered, "later asset linker bypassed waiting compaction")
	close(releaseCompaction)

	var releaseSecond func()
	select {
	case releaseSecond = <-secondEntered:
	case <-time.After(time.Second):
		t.Fatal("later asset linker did not acquire the released session gate")
	}
	releaseSecond()
}

func TestSynchronousSessionCompactionSuspendsOnlyItsOwnAssetLinker(t *testing.T) {
	t.Parallel()

	resolver := &Service{}
	releaseCurrent := resolver.DeferSessionCompaction("bot-1", "session-1", "run-current")
	releaseOther := resolver.DeferSessionCompaction("bot-1", "session-1", "run-other")
	compactionEntered := make(chan func(), 1)
	go func() {
		compactionEntered <- resolver.enterSessionCompactionForRun("bot-1", "session-1", "run-current")
	}()

	assertChannelBlocked(t, compactionEntered, "sync compaction ignored another run.s asset linker")
	releaseOther()
	var finishCompaction func()
	select {
	case finishCompaction = <-compactionEntered:
	case <-time.After(time.Second):
		t.Fatal("sync compaction did not suspend its own asset linker")
	}
	finishCompaction()

	asyncEntered := make(chan struct{})
	go func() {
		done := resolver.enterSessionCompaction("bot-1", "session-1")
		close(asyncEntered)
		done()
	}()
	assertChannelBlocked(t, asyncEntered, "sync compaction did not restore its run.s asset linker")
	releaseCurrent()
	assertChannelReady(t, asyncEntered, "restored asset linker did not release async compaction")
}

func TestConcurrentSynchronousSessionCompactionsDoNotDeadlockUpgradingReaders(t *testing.T) {
	t.Parallel()

	resolver := &Service{}
	releaseFirst := resolver.DeferSessionCompaction("bot-1", "session-1", "run-1")
	releaseSecond := resolver.DeferSessionCompaction("bot-1", "session-1", "run-2")
	type enteredCompaction struct {
		release       chan struct{}
		done          chan struct{}
		releaseReader func()
	}
	entered := make(chan enteredCompaction, 2)
	releaseReaders := map[string]func(){"run-1": releaseFirst, "run-2": releaseSecond}
	for _, runID := range []string{"run-1", "run-2"} {
		go func() {
			finish := resolver.enterSessionCompactionForRun("bot-1", "session-1", runID)
			release := make(chan struct{})
			done := make(chan struct{})
			entered <- enteredCompaction{release: release, done: done, releaseReader: releaseReaders[runID]}
			<-release
			finish()
			close(done)
		}()
	}

	var first enteredCompaction
	select {
	case first = <-entered:
	case <-time.After(time.Second):
		t.Fatal("neither sync compaction upgraded its reader")
	}
	close(first.release)
	first.releaseReader()
	var second enteredCompaction
	select {
	case second = <-entered:
	case <-time.After(time.Second):
		t.Fatal("second sync compaction deadlocked while upgrading its reader")
	}
	close(second.release)
	assertChannelReady(t, first.done, "first sync compaction did not restore its reader")
	assertChannelReady(t, second.done, "second sync compaction did not restore its reader")
	second.releaseReader()
}

func assertChannelBlocked[T any](t *testing.T, ch <-chan T, message string) {
	t.Helper()
	select {
	case <-ch:
		t.Fatal(message)
	case <-time.After(20 * time.Millisecond):
	}
}

func assertChannelReady[T any](t *testing.T, ch <-chan T, message string) {
	t.Helper()
	select {
	case <-ch:
	case <-time.After(time.Second):
		t.Fatal(message)
	}
}

